EXAMPLES=[]
for n,q,steps,ans,p in [
 ('13','Find tangent lengths from P(3,4) to (a) x²+y² = 9 and (b) x²+y²−2x−y−3 = 0.',['For a genuine circle, tangent length squared is the point’s power PC²−r².','(a) The center is the origin and radius is 3. The point’s squared center distance is 3²+4² = 25.','Thus PT² = 25−9 = 16 > 0 and PT = 4.','The source figure gives contact T(3,0): it is on the circle, the line x = 3 is tangent, and the segment from (3,4) has length 4.','(b) Directly evaluate the normalized circle polynomial at P: 9+16−6−4−3 = 12.','Hence both tangent lengths are √12 = 2√3.','Independently, the second circle has center (1,1/2), squared radius 17/4, and PC² = 4+49/4 = 65/4. Their difference is 48/4 = 12, confirming the result.'],'(a) 4; (b) 2√3.',229),
 ('14','Find the tangents from (6,4) to x²+y² = 16.',['The point’s squared center distance is 36+16 = 52 > 16, so two real tangents exist.','A line of slope m through the point is y−4 = m(x−6), with intercept c = 4−6m.','Tangency requires c² = 16(1+m²). Expanding gives 20m²−48m = 0.','Thus m = 0 or 12/5. The first line is y = 4.','The second line is y−4 = (12/5)(x−6), or 12x−5y−52 = 0.','Check point incidence: 4 = 4 and 72−20−52 = 0.','Center-to-line distances are 4 and 52/√169 = 4, proving both are tangent.','The contacts are (0,4) and (48/13,−20/13). Each has squared norm 16 and lies on its tangent. Both tangent-segment lengths from (6,4) are √(52−16) = 6.'],'y = 4 and 12x−5y−52 = 0.',230)]:
 EXAMPLES.append({'num':n,'title':'External Tangents','question':q,'steps':steps,'answer':ans,'progressiveSolution':True,'solutionOrigin':'SpaceBook learning enhancement','sourceReferences':[{'page':p,'jpg':'119_page_1.jpg' if p==229 else '119_page_2.jpg','verification':'Complete source question and selected tangent branches visually checked'}],**({'sourceQuestionBlocks':[tangent_length_graph()]} if n=='13' else {})})
